package com.citacloud.app.models;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="movimientos_inventario") public class MovimientoInventario { @Id @GeneratedValue private UUID id; @Column(name="empresa_id") private UUID empresaId; @ManyToOne @JoinColumn(name="sucursal_id") private Sucursal sucursal; @ManyToOne @JoinColumn(name="producto_id") private ProductoInventario producto; @ManyToOne @JoinColumn(name="lote_id") private LoteInventario lote; private String numero; private String tipo; private String motivo; private BigDecimal cantidad; @Column(name="stock_anterior") private BigDecimal stockAnterior; @Column(name="stock_posterior") private BigDecimal stockPosterior; @Column(name="costo_unitario") private BigDecimal costoUnitario; private String referencia; private String observacion; @Column(name="creado_por") private UUID creadoPor; @Column(name="creado_en") private LocalDateTime creadoEn=LocalDateTime.now(); public UUID getId(){return id;} public String getNumero(){return numero;} public void setNumero(String v){numero=v;} public String getTipo(){return tipo;} public void setTipo(String v){tipo=v;} public String getMotivo(){return motivo;} public void setMotivo(String v){motivo=v;} public BigDecimal getCantidad(){return cantidad;} public void setCantidad(BigDecimal v){cantidad=v;} public BigDecimal getStockAnterior(){return stockAnterior;} public void setStockAnterior(BigDecimal v){stockAnterior=v;} public BigDecimal getStockPosterior(){return stockPosterior;} public void setStockPosterior(BigDecimal v){stockPosterior=v;} public LocalDateTime getCreadoEn(){return creadoEn;} public ProductoInventario getProducto(){return producto;} public Sucursal getSucursal(){return sucursal;} public LoteInventario getLote(){return lote;} public void setEmpresaId(UUID v){empresaId=v;} public void setSucursal(Sucursal v){sucursal=v;} public void setProducto(ProductoInventario v){producto=v;} public void setLote(LoteInventario v){lote=v;} public void setCostoUnitario(BigDecimal v){costoUnitario=v;} public void setReferencia(String v){referencia=v;} public void setObservacion(String v){observacion=v;} public void setCreadoPor(UUID v){creadoPor=v;} }
